package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.ruoyi.medical.persistence.TaskRunActivityJournal.*;

/** Actual RN-05 reuse producer. Preserves every original object/receipt and never
 * creates a dispatch, session, invocation, charge, or successor lease. */
@org.springframework.stereotype.Component
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="medical.professional-runtime.task-enabled",havingValue="true",matchIfMissing=false)
public final class TaskRunSuccessReuse {
    static final String ACTION="task.run.success.reused.v1";
    static final String MANIFEST=org.apache.commons.codec.digest.DigestUtils.sha256Hex("TASK_SUCCESS_REUSE_V1:original-N02-N03-N04-N05-commit:lease-zero:no-dispatch:exact-semantic-input");
    private final JdbcTemplate db;private final PermissionSchema json;private final TaskRunResumeOriginalAuthority originals;private final TaskResearchCompletionAuthority completions;
    private final JsonMapper reader=new JsonMapper();
    public TaskRunSuccessReuse(@org.springframework.beans.factory.annotation.Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskRunResumeOriginalAuthority originals,TaskResearchCompletionAuthority completions){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.originals=originals;this.completions=completions;}
    private org.springframework.beans.factory.ObjectProvider<TaskSectionWriterInputAuthority> writerInputs;
    private org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierInputAuthority> verifierInputs;
    private org.springframework.beans.factory.ObjectProvider<TaskSectionWriterStageCommitService> writerCommits;
    private org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierStageCommitService> verifierCommits;
    @org.springframework.beans.factory.annotation.Autowired
    void stageReaders(org.springframework.beans.factory.ObjectProvider<TaskSectionWriterInputAuthority> wi,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierInputAuthority> vi,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterStageCommitService> wc,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierStageCommitService> vc){writerInputs=wi;verifierInputs=vi;writerCommits=wc;verifierCommits=vc;}
    private org.springframework.beans.factory.ObjectProvider<TaskStrictFieldPreparation> fieldPreparation;
    private org.springframework.beans.factory.ObjectProvider<TaskStrictFieldWriterReadAuthority> fieldReaders;
    @org.springframework.beans.factory.annotation.Autowired void fields(org.springframework.beans.factory.ObjectProvider<TaskStrictFieldPreparation> prep,org.springframework.beans.factory.ObjectProvider<TaskStrictFieldWriterReadAuthority> readers){fieldPreparation=prep;fieldReaders=readers;}
    void materializeField(TaskRunActivityPreparation.Current c)throws Exception {
        c.requireUnchanged();var p=c.production();if(!c.graph().requiredStages().contains("N03"))return;
        var links=db.queryForList("SELECT parent_run_id FROM task_run_continuation WHERE tenant_id=? AND run_id=? AND mode='RESUME' LIMIT 2 FOR UPDATE",p.tenantId(),p.runId());if(links.isEmpty())return;
        for(var node:c.graph().nodes()){var states=db.queryForList("SELECT status FROM run_step WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",p.tenantId(),p.runId(),node.stepId());if(states.isEmpty()||!"SUCCEEDED".equals(text(one(states),"status")))return;}
        var old=db.queryForList("SELECT s.step_id FROM run_step s JOIN runtime_node_definition d ON d.tenant_id=s.tenant_id AND d.run_id=s.run_id AND d.step_id=s.step_id WHERE s.tenant_id=? AND s.run_id=? AND s.status='SUCCEEDED' AND d.node_kind='N03' LIMIT 2 FOR UPDATE",p.tenantId(),text(one(links),"parent_run_id"));if(old.isEmpty())return;
        var existing=db.queryForList("SELECT step_id FROM task_strict_field_input WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",p.tenantId(),p.runId());if(!existing.isEmpty()&&read(db,json,p.admission(),p.runId(),text(one(existing),"step_id")).isPresent())return;
        fieldPreparation.getObject().materialize(c);String step=text(one(db.queryForList("SELECT step_id FROM task_strict_field_input WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",p.tenantId(),p.runId())),"step_id");var source=originals.require(p,"N03",step,text(one(old),"step_id"));var proof=fieldReaders.getObject().requireOriginal(source,c.publication(),c.policy());proof.requireUnchanged();save(c,source,proof.originalReceipt(),proof.originalReceiptId(),proof.originalReceiptSha256());proof.requireUnchanged();
    }
    void materializeStage(TaskRunActivityPreparation.Current c,String stage,String step)throws Exception {
        c.requireUnchanged();var p=c.production();if(read(db,json,p.admission(),p.runId(),step).isPresent())return;
        var links=db.queryForList("SELECT parent_run_id FROM task_run_continuation WHERE tenant_id=? AND run_id=? AND mode='RESUME' LIMIT 2 FOR UPDATE",p.tenantId(),p.runId());if(links.isEmpty())return;String parent=text(one(links),"parent_run_id");
        List<Map<String,Object>> rows;
        if("N04".equals(stage))rows=db.queryForList("SELECT old.step_id FROM run_step old JOIN run_step current ON current.tenant_id=old.tenant_id AND current.section_id=old.section_id JOIN runtime_node_definition d ON d.tenant_id=old.tenant_id AND d.run_id=old.run_id AND d.step_id=old.step_id AND d.node_kind='N04' WHERE old.tenant_id=? AND old.run_id=? AND old.status='SUCCEEDED' AND current.run_id=? AND current.step_id=? LIMIT 2 FOR UPDATE",p.tenantId(),parent,p.runId(),step);
        else if("N05".equals(stage))rows=db.queryForList("SELECT old.step_id FROM task_source_verifier_input old JOIN task_source_verifier_input current ON current.tenant_id=old.tenant_id AND current.canonical_input->>'$.candidate_id'=old.canonical_input->>'$.candidate_id' JOIN run_step s ON s.tenant_id=old.tenant_id AND s.run_id=old.run_id AND s.step_id=old.step_id WHERE old.tenant_id=? AND old.run_id=? AND s.status='SUCCEEDED' AND current.run_id=? AND current.step_id=? LIMIT 2 FOR UPDATE",p.tenantId(),parent,p.runId(),step);
        else throw new IllegalArgumentException("unsupported stage");
        if(rows.isEmpty())return;var source=originals.require(p,stage,step,text(one(rows),"step_id"));
        if("N04".equals(stage))record(c,writerCommits.getObject().requireForConsumer(writerInputs.getObject().requireOriginal(source,c.publication(),c.policy())));
        else record(c,verifierCommits.getObject().requireForConsumer(verifierInputs.getObject().requireOriginal(source,c.publication(),c.policy())));
    }
    void record(TaskRunActivityPreparation.Current c,TaskSectionWriterStageCommitService.ForConsumer proof)throws Exception {proof.requireUnchanged();save(c,proof.source(),proof.originalReceipt(),proof.originalReceiptId(),proof.originalReceiptSha256());proof.requireUnchanged();}
    void record(TaskRunActivityPreparation.Current c,TaskSourceVerifierStageCommitService.ForConsumer proof)throws Exception {proof.requireUnchanged();save(c,proof.source(),proof.originalReceipt(),proof.originalReceiptId(),proof.originalReceiptSha256());proof.requireUnchanged();}
    private void save(TaskRunActivityPreparation.Current current,TaskRunResumeOriginalAuthority.Source source,JsonNode original,String receiptId,String receiptHash)throws Exception {
        current.requireUnchanged();source.requireUnchanged();var p=current.production();same(p.runId(),source.successorRunId());same(hash(original),receiptHash);String step=source.successorStepId(),stage=source.stageKind();
        var value=json.object().put("schema_version","1.0.0").put("kind","ORIGINAL_SUCCESS_REUSE").put("stage_kind",stage).put("run_id",p.runId()).put("step_id",step).put("input_sha256",source.pins().required("successor_input_sha256").asText()).put("lease_generation",0).put("original_run_id",source.originalRunId()).put("original_step_id",source.originalStepId()).put("original_receipt_sha256",receiptHash).put("original_receipt_id",receiptId);value.set("outputs",source.pins().required("original_outputs"));value.set("source",source.pins());value.set("original_receipt",original);
        String id=derived(p.runId(),ACTION+":"+step);var journal=new TaskRunActivityJournal(db,json);journal.write(p.admission(),p.projectId(),p.runId(),id,ACTION,ACTION+":"+p.runId()+":"+step,step,hash(source.pins()),p.classification(),"1.0.0",MANIFEST,value);
        changed(db.update("INSERT INTO task_run_success_reuse(tenant_id,project_id,run_id,step_id,original_run_id,original_step_id,stage_kind,operation_id,receipt_json,receipt_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,UTC_TIMESTAMP(6),?)",p.tenantId(),p.projectId(),p.runId(),step,source.originalRunId(),source.originalStepId(),stage,id,json.canonical(value),hash(value),MANIFEST,p.actorId(),p.classification()));
        changed(db.update("UPDATE run_step SET status='SUCCEEDED',output_ref=?,revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND status='READY' AND lease_generation=0 AND lease_owner IS NULL AND lease_expires_at IS NULL AND input_sha256=?",json.canonical(value.required("outputs")),p.tenantId(),p.projectId(),p.runId(),step,value.required("input_sha256").asText()));source.requireUnchanged();current.requireUnchanged();
    }
    void materializeResearch(TaskRunActivityPreparation.Current current,String step)throws Exception {
        current.requireUnchanged();var p=current.production();var links=db.queryForList("SELECT parent_run_id FROM task_run_continuation WHERE tenant_id=? AND run_id=? AND mode='RESUME' LIMIT 2 FOR UPDATE",p.tenantId(),p.runId());if(links.isEmpty())return;String parent=text(one(links),"parent_run_id");
        if(read(db,json,p.admission(),p.runId(),step).isPresent())return;
        var target=one(db.queryForList("SELECT question_id FROM task_node_input_intent WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",p.tenantId(),p.runId(),step));
        var rows=db.queryForList("SELECT i.step_id FROM task_node_input_intent i JOIN run_step s ON s.tenant_id=i.tenant_id AND s.run_id=i.run_id AND s.step_id=i.step_id WHERE i.tenant_id=? AND i.run_id=? AND i.question_id=? AND s.status='SUCCEEDED' LIMIT 2 FOR UPDATE",p.tenantId(),parent,text(target,"question_id"));if(rows.isEmpty())return;
        var source=originals.require(p,"N02",step,text(one(rows),"step_id"));var proof=completions.requireOriginal(source);proof.requireUnchanged();
        var original=one(db.queryForList("SELECT canonical_receipt,receipt_sha256 FROM run_runtime_receipt WHERE tenant_id=? AND run_id=? AND command_kind='COMMIT' AND canonical_request->>'$.step_id'=? LIMIT 2 FOR UPDATE",p.tenantId(),source.originalRunId(),source.originalStepId()));var receipt=reader.readTree(text(original,"canonical_receipt"));same(proof.completionReceiptSha256(),text(original,"receipt_sha256"));same(proof.completionReceiptSha256(),hash(receipt));same("SUCCEEDED",receipt.required("status").asText());
        var value=json.object().put("schema_version","1.0.0").put("kind","ORIGINAL_SUCCESS_REUSE").put("stage_kind","N02").put("run_id",p.runId()).put("step_id",step).put("input_sha256",source.pins().required("successor_input_sha256").asText()).put("lease_generation",0).put("original_run_id",source.originalRunId()).put("original_step_id",source.originalStepId()).put("original_receipt_sha256",proof.completionReceiptSha256());value.put("original_receipt_id",receipt.required("receiptId").asText());value.set("outputs",receipt.required("outputs"));value.set("source",source.pins());value.set("original_receipt",receipt);
        String id=derived(p.runId(),ACTION+":"+step),raw=json.canonical(value);var journal=new TaskRunActivityJournal(db,json);journal.write(p.admission(),p.projectId(),p.runId(),id,ACTION,ACTION+":"+p.runId()+":"+step,step,hash(source.pins()),p.classification(),"1.0.0",MANIFEST,value);
        changed(db.update("INSERT INTO task_run_success_reuse(tenant_id,project_id,run_id,step_id,original_run_id,original_step_id,stage_kind,operation_id,receipt_json,receipt_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,'N02',?,?,?,'1.0.0',?,?,UTC_TIMESTAMP(6),?)",p.tenantId(),p.projectId(),p.runId(),step,source.originalRunId(),source.originalStepId(),id,raw,hash(value),MANIFEST,p.actorId(),p.classification()));
        proof.requireUnchanged();source.requireUnchanged();changed(db.update("UPDATE run_step SET status='SUCCEEDED',output_ref=?,revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND status='READY' AND lease_generation=0 AND lease_owner IS NULL AND lease_expires_at IS NULL AND input_sha256=?",json.canonical(receipt.required("outputs")),p.tenantId(),p.projectId(),p.runId(),step,value.required("input_sha256").asText()));current.requireUnchanged();
    }
    Optional<TaskResearchCompletionAuthority.Verified> completion(EnterpriseAccess.Admission a,String run,String step)throws Exception {
        if(read(db,json,a,run,step).isEmpty())return Optional.empty();var source=originals.requireSaved(a,run,step);return Optional.of(completions.requireOriginal(source));
    }
    static Optional<JsonNode> read(JdbcTemplate db,PermissionSchema json,EnterpriseAccess.Admission a,String run,String step)throws Exception {
        var rows=db.queryForList("SELECT * FROM task_run_success_reuse WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),run,step);if(rows.isEmpty())return Optional.empty();var row=one(rows);var parser=new JsonMapper();var value=parser.readTree(text(row,"receipt_json"));same(hash(value),text(row,"receipt_sha256"));same("1.0.0",text(row,"schema_version"));same(MANIFEST,text(row,"schema_manifest_sha256"));same(a.actorId(),text(row,"created_by"));same(run,value.required("run_id").asText());same(step,value.required("step_id").asText());same(0,value.required("lease_generation").intValue());same(text(row,"original_run_id"),value.required("original_run_id").asText());same(text(row,"original_step_id"),value.required("original_step_id").asText());same(hash(value.required("original_receipt")),value.required("original_receipt_sha256").asText());if("N02".equals(value.required("stage_kind").asText()))same("SUCCEEDED",value.required("original_receipt").required("status").asText());
        same("ORIGINAL_SUCCESS_REUSE",value.required("kind").asText());same("1.0.0",value.required("schema_version").asText());same(text(row,"stage_kind"),value.required("stage_kind").asText());
        var pins=value.required("source");same(run,pins.required("successor_run_id").asText());same(step,pins.required("successor_step_id").asText());same(value.required("original_run_id"),pins.required("parent_run_id"));same(value.required("original_step_id"),pins.required("original_step_id"));same(value.required("input_sha256"),pins.required("successor_input_sha256"));same(value.required("outputs"),pins.required("original_outputs"));
        var origin=one(db.queryForList("SELECT s.status,s.input_sha256,s.output_ref,s.lease_generation,d.canonical_definition,d.definition_sha256,r.ended_at,r.dispatch_closed_at,r.created_by,r.classification FROM run_step s JOIN runtime_node_definition d ON d.tenant_id=s.tenant_id AND d.run_id=s.run_id AND d.step_id=s.step_id JOIN task_run r ON r.tenant_id=s.tenant_id AND r.run_id=s.run_id WHERE s.tenant_id=? AND s.project_id=? AND s.run_id=? AND s.step_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),text(row,"project_id"),text(row,"original_run_id"),text(row,"original_step_id")));
        same("SUCCEEDED",text(origin,"status"));same(a.actorId(),text(origin,"created_by"));same(text(row,"classification"),text(origin,"classification"));if(origin.get("ended_at")==null||origin.get("dispatch_closed_at")==null)bad();same(text(origin,"input_sha256"),pins.required("original_input_sha256").asText());same(number(origin,"lease_generation"),pins.required("original_generation").asText());same(parser.readTree(text(origin,"output_ref")),value.required("outputs"));same(parser.readTree(text(origin,"canonical_definition")),pins.required("original_definition"));same(hash(pins.required("original_definition")),text(origin,"definition_sha256"));
        String stage=text(row,"stage_kind");var receipt=value.required("original_receipt");
        if("N02".equals(stage)){var committed=one(db.queryForList("SELECT canonical_receipt,receipt_sha256 FROM run_runtime_receipt WHERE tenant_id=? AND run_id=? AND command_kind='COMMIT' AND canonical_request->>'$.step_id'=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),text(row,"original_run_id"),text(row,"original_step_id")));same(receipt,parser.readTree(text(committed,"canonical_receipt")));same(value.required("original_receipt_sha256").asText(),text(committed,"receipt_sha256"));same(value.required("original_receipt_id").asText(),receipt.required("receiptId").asText());}
        else if("N03".equals(stage)){
            var completion=receipt.required("completion");String command=completion.required("commandId").asText();
            var op=one(db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND operation_id=? AND operation_name=? AND target_id=? AND state='COMPLETED' LIMIT 2 FOR UPDATE",a.context().tenant_id(),value.required("original_receipt_id").asText(),TaskRunStageCommitServiceV2.ACTION,text(row,"original_run_id")));
            var witness=new TaskRunActivityJournal(db,json).read(a,text(row,"project_id"),text(row,"original_run_id"),text(op,"operation_id"),TaskRunStageCommitServiceV2.ACTION,text(op,"idempotency_key"),command,hash(completion),text(row,"classification"),"2.0.0",TaskRunStageCommitServiceV2.MANIFEST).orElseThrow();same(receipt,witness.required("receipt"));same(hash(witness.required("body")),receipt.required("receiptSha256").asText());same("SATISFIED",receipt.required("disposition").asText());same(value.required("original_receipt_id").asText(),receipt.required("receiptId").asText());
        }
        else if(Set.of("N04","N05").contains(stage)){
            String action="N04".equals(stage)?TaskSectionWriterStageCommitService.ACTION:TaskSourceVerifierStageCommitService.ACTION;
            var operation=one(db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND operation_id=? AND target_id=? AND operation_name=? AND state='COMPLETED' LIMIT 2 FOR UPDATE",a.context().tenant_id(),value.required("original_receipt_id").asText(),text(row,"original_run_id"),action));
            var witness=new TaskRunActivityJournal(db,json).read(a,text(row,"project_id"),text(row,"original_run_id"),text(operation,"operation_id"),action,text(operation,"idempotency_key"),receipt.required("original").required("command").required("command_id").asText(),hash(receipt.required("original")),text(row,"classification"),"1.0.0","N04".equals(stage)?TaskSectionWriterStageCommitService.MANIFEST:TaskSourceVerifierStageCommitService.MANIFEST).orElseThrow();same(receipt,witness.required("receipt"));same(hash(witness.required("body")),receipt.required("receipt_sha256").asText());same(value.required("original_receipt_id").asText(),receipt.required("receipt_id").asText());
            if("N05".equals(stage)&&!receipt.required("review").required("passed").booleanValue())bad();
        }
        RunContinuationService.requireSuccessor(db,a,run);var journal=new TaskRunActivityJournal(db,json);same(value,journal.read(a,text(row,"project_id"),run,text(row,"operation_id"),ACTION,ACTION+":"+run+":"+step,step,hash(value.required("source")),text(row,"classification"),"1.0.0",MANIFEST).orElseThrow());
        var next=one(db.queryForList("SELECT status,input_sha256,lease_generation,lease_owner,lease_expires_at,output_ref FROM run_step WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),run,step));same("SUCCEEDED",text(next,"status"));same("0",number(next,"lease_generation"));if(next.get("lease_owner")!=null||next.get("lease_expires_at")!=null)bad();same(value.required("input_sha256").asText(),text(next,"input_sha256"));same(value.required("outputs"),parser.readTree(text(next,"output_ref")));var definition=one(db.queryForList("SELECT node_kind,canonical_definition,definition_sha256 FROM runtime_node_definition WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),run,step));same(stage,text(definition,"node_kind"));same(pins.required("successor_definition"),parser.readTree(text(definition,"canonical_definition")));same(hash(pins.required("successor_definition")),text(definition,"definition_sha256"));return Optional.of(value);
    }
    static List<JsonNode> inventory(JdbcTemplate db,PermissionSchema json,EnterpriseAccess.Admission a,String run,int limit)throws Exception {
        var rows=db.queryForList("SELECT step_id FROM task_run_success_reuse WHERE tenant_id=? AND run_id=? ORDER BY step_id LIMIT ? FOR UPDATE",a.context().tenant_id(),run,limit+1);if(rows.size()>limit)bad();var result=new ArrayList<JsonNode>();for(var row:rows)result.add(read(db,json,a,run,text(row,"step_id")).orElseThrow());return List.copyOf(result);
    }
    static boolean satisfiesStage(JdbcTemplate db,TaskRunLifecycleAuthority.Proof p,String stage,List<JsonNode> reused,Set<String> committed){return org.springframework.util.function.ThrowingSupplier.of(()->satisfiesStageChecked(db,p,stage,reused,committed)).get();}
    private static boolean satisfiesStageChecked(JdbcTemplate db,TaskRunLifecycleAuthority.Proof p,String stage,List<JsonNode> reused,Set<String> committed)throws Exception {
        var rows=db.queryForList("SELECT s.step_id,s.section_id FROM run_step s JOIN runtime_node_definition d ON d.tenant_id=s.tenant_id AND d.run_id=s.run_id AND d.step_id=s.step_id WHERE s.tenant_id=? AND s.run_id=? AND d.node_kind=? FOR UPDATE",p.reference().tenantId(),p.reference().runId(),stage);
        var expected=new HashSet<String>();p.graph().nodes().forEach(n->expected.add(n.sectionId()));var seen=new HashSet<String>();if(rows.isEmpty())return false;
        for(var row:rows){String id=text(row,"step_id");if(!committed.contains(id)&&reused.stream().noneMatch(r->stage.equals(r.required("stage_kind").asText())&&id.equals(r.required("step_id").asText())))return false;if(!seen.add(text(row,"section_id")))return false;}
        return expected.equals(seen);
    }
    static boolean exists(JdbcTemplate db,String tenant,String run,String step){return !db.queryForList("SELECT step_id FROM task_run_success_reuse WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 1",tenant,run,step).isEmpty();}
    private static String hash(JsonNode n)throws Exception{return com.ruoyi.medical.contracts.WireValues.sha256(ContentReadAuthorization.canonicalBytes(n));}
}
